WITH RankedPosts AS (SELECT p.Id AS PostId, p.Title, p.CreationDate, p.Score, COALESCE(pc.CommentCount, 0) AS CommentCount, COALESCE(a.AnswerCount, 0) AS AnswerCount, ROW_NUMBER() OVER (PARTITION BY p.OwnerUserId ORDER BY p.CreationDate DESC NULLS FIRST) AS PostRank FROM Posts AS p LEFT JOIN (SELECT PostId, COUNT(*) AS CommentCount FROM Comments GROUP BY PostId) AS pc ON p.Id = pc.PostId LEFT JOIN (SELECT ParentId AS AnswerId, COUNT(*) AS AnswerCount FROM Posts WHERE PostTypeId = 2 GROUP BY ParentId) AS a ON p.Id = a.AnswerId WHERE p.PostTypeId = 1), UserBadges AS (SELECT UserId, COUNT(*) AS BadgeCount, GROUP_CONCAT(Name, ', ') AS BadgeNames FROM Badges GROUP BY UserId), PostHistoryAggregated AS (SELECT ph.PostId, GROUP_CONCAT(ph.Comment, ' | ') AS HistoryComments FROM PostHistory AS ph WHERE ph.CreationDate >= CAST('2024-10-01 12:34:56' AS Nullable(DateTime)) - INTERVAL '30' DAYS GROUP BY ph.PostId) SELECT up.DisplayName, rp.PostId, rp.Title, rp.CreationDate, rp.Score, rp.CommentCount, rp.AnswerCount, ub.BadgeCount, ub.BadgeNames, COALESCE(ph.HistoryComments, 'No recent changes') AS RecentHistory FROM RankedPosts AS rp JOIN Users AS up ON rp.PostId = up.Id LEFT JOIN UserBadges AS ub ON up.Id = ub.UserId LEFT JOIN PostHistoryAggregated AS ph ON rp.PostId = ph.PostId WHERE rp.PostRank = 1 AND (ub.BadgeCount > 3 OR NOT (ub.BadgeNames IS NULL)) ORDER BY rp.Score DESC NULLS FIRST, rp.CreationDate DESC NULLS FIRST LIMIT 50